RAW=sql("SELECT sa.code AS theater,ca.status,ca.config->>'promoMode' AS promo_mode,ca.config->'agencyIds' AS agency_ids FROM channel_app ca JOIN source_app sa ON sa.id=ca.source_app_id ORDER BY sa.code;\nSELECT sa.code,cc.capability_key,cc.status FROM channel_capability cc JOIN channel_app ca ON ca.id=cc.channel_app_id JOIN source_app sa ON sa.id=ca.source_app_id ORDER BY sa.code,cc.capability_key;\nSELECT json_build_object('apps',(SELECT json_agg(json_build_object('theater',sa.code,'id',ca.id,'status',ca.status,'promoMode',ca.config->>'promoMode','agencyIds',ca.config->'agencyIds','codeModeLocales',ca.config->'codeModeLocales','appDisplayName',ca.config->>'appDisplayName') ORDER BY sa.code) FROM channel_app ca JOIN source_app sa ON sa.id=ca.source_app_id WHERE sa.code IN ('plotnovel','moboreader')),'plotnovelCapabilities',(SELECT json_object_agg(cc.capability_key,cc.status) FROM channel_capability cc JOIN channel_app ca ON ca.id=cc.channel_app_id JOIN source_app sa ON sa.id=ca.source_app_id WHERE sa.code='plotnovel'),'storeLinks',(SELECT json_build_object('appStorePresent',coalesce(length(ca.config->>'appStoreUrl')>0,false),'appStoreMatches',ca.config->>'appStoreUrl'='https://apps.apple.com/app/plotnovel/id6749878264','googlePlayPresent',coalesce(length(ca.config->>'googlePlayUrl')>0,false),'googlePlayMatches',ca.config->>'googlePlayUrl'='https://play.google.com/store/apps/details?id=com.plot.novel_app') FROM channel_app ca JOIN source_app sa ON sa.id=ca.source_app_id WHERE sa.code='plotnovel'));\n")
print('REGISTRATION_READBACK_BEGIN');print(RAW,end='');print('REGISTRATION_READBACK_END')
x=next(json.loads(l) for l in RAW.splitlines() if l.startswith('{'));p=next(a for a in x['apps'] if a['theater']=='plotnovel');m=next(a for a in x['apps'] if a['theater']=='moboreader')
assert p['status']=='registered_disabled' and p['promoMode']=='code' and p['agencyIds']==['1351'] and p['codeModeLocales']==['en'] and p['appDisplayName']=='PlotNovel', 'PlotNovel metadata readback mismatch'
assert m['status']=='active' and m['promoMode']=='link' and m['agencyIds']==['3366'], 'MoboReader metadata readback mismatch'
